def second_smallest(lst):
    if len(lst) < 2:
        raise ValueError("List must contain at least two elements")
    unique_vals = set(lst)
    if len(unique_vals) < 2:
        raise ValueError("List must contain at least two distinct elements")
    smallest = min(unique_vals)
    unique_vals.remove(smallest)
    return min(unique_vals)

import re

def remove_multiple_spaces(s: str) -> str:
    # Replace sequences of 2 or more whitespace characters with a single space
    return re.sub(r'\s{2,}', ' ', s)

def is_decimal(s: str) -> bool:
    if not s or s.count('.') > 1:
        return False

    # Allow optional leading sign
    if s[0] in '+-':
        s = s[1:]
        if not s:
            return False

    parts = s.split('.')
    if len(parts) == 1:
        # No decimal point, just check if integer
        return parts[0].isdigit()
    elif len(parts) == 2:
        int_part, dec_part = parts
        # int_part can be empty (e.g. ".99"), dec_part can be empty (e.g. "1.")
        if (int_part and not int_part.isdigit()) or (dec_part and not dec_part.isdigit()):
            return False
        return len(dec_part) <= 2
    else:
        return False

def is_Two_Alter(s):
    if len(s) < 2:
        return False

    s_lower = s.lower()
    distinct_chars = set(s_lower)
    if len(distinct_chars) != 2:
        return False

    for i in range(1, len(s_lower)):
        if s_lower[i] == s_lower[i - 1]:
            return False

    return True

def max_sub_array_sum(arr):
    if not arr:
        return 0
    max_ending_here = max_so_far = arr[0]
    for x in arr[1:]:
        max_ending_here = max(x, max_ending_here + x)
        max_so_far = max(max_so_far, max_ending_here)
    return max_so_far

