def minPath(grid, k):
    N = len(grid)
    if k == 0:
        return []
    # Directions for neighbors
    directions = [(-1,0),(1,0),(0,-1),(0,1)]

    # Initialize frontier with all starting cells paths of length 1
    # Each element: (path_tuple, r, c)
    frontier = []
    for r in range(N):
        for c in range(N):
            frontier.append(((grid[r][c],), r, c))

    # For step 1 to k-1, extend paths
    for step in range(1, k):
        next_frontier = []
        for path, r, c in frontier:
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    new_path = path + (grid[nr][nc],)
                    next_frontier.append((new_path, nr, nc))

        if not next_frontier:
            # No further paths possible
            return []

        # Find minimal lex path among next_frontier
        min_path = min(p for p, rr, cc in next_frontier)

        # Keep only paths with minimal lex prefix
        frontier = [x for x in next_frontier if x[0] == min_path]

    # After k steps, frontier contains only minimal lex path(s)
    # By uniqueness, only one minimal lex path remains
    if not frontier:
        return []
    return list(frontier[0][0])

def cycpattern_check(a, b):
