from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()
    depths = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif char == ')':
                current_depth -= 1
        depths.append(max_depth)
    return depths

def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    # From the example:
    # 'This is a test' -> output: 'is'
    # Words with prime length: 'is' (2), 'a' (1), 'test' (4)
    # 'a' length 1 is not prime,
    # 'is' length 2 prime,
    # 'test' length 4 not prime
    # So only 'is' is prime length word.
    # Hence the filter should be words whose length is prime.
    prime_length_words = [w for w in words if is_prime(len(w))]
    return " ".join(prime_length_words)

