def special_factorial(n):
    from math import factorial
    result = 1
    for i in range(1, n + 1):
        result *= factorial(i)
    return result

def even_odd_palindrome(n):
    even_count = 0
    odd_count = 0

    for num in range(1, n + 1):
        s = str(num)
        if s == s[::-1]:
            # Count even and odd numbers, not digits
            if num % 2 == 0:
                even_count += 1
            else:
                odd_count += 1
    return (odd_count, even_count)

def correct_bracketing(brackets: str):
    count = 0
    for ch in brackets:
        if ch == '<':
            count += 1
        elif ch == '>':
            count -= 1
            if count < 0:
                return False
    return count == 0
